export const EXTRA_KANJI: KanjiEntry[] = PACKED.split("\n").map((line) => {
  const [kanji, on, kun, meaning] = line.split("|");
  return {
    kanji,
    on: on ? on.split(",") : [],
    kun: kun ? kun.split(",") : [],
    meaning,
  };
});
